{
  "name": "alchemyst-threshold-cli",
  "version": "1.0.0",
  "description": "Alchemyst AI Threshold Sensitivity CLI",
  "main": "dist/main.js",
  "scripts": {
    "build": "tsc",
    "start": "node dist/main.js"
  },
  "dependencies": {
    "@alchemystai/sdk": "^1.0.0"
  },
  "devDependencies": {
    "@types/node": "^18.15.0",
    "typescript": "^5.0.0"
  }
}

{
  "name": "alchemyst-threshold-cli",
  "version": "1.0.0",
  "description": "Alchemyst AI Threshold Sensitivity CLI",
  "main": "dist/main.js",
  "scripts": {
    "build": "tsc",
    "start": "node dist/main.js"
  },
  "dependencies": {
    "@alchemystai/sdk": "^0.11.1"
  },
  "devDependencies": {
    "@types/node": "^18.15.0",
    "typescript": "^5.0.0"
  }
}

import * as fs from 'fs';
import * as path from 'path';
import AlchemystAI from '@alchemystai/sdk';

async function main() {
  // 1. Verify API Key
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!apiKey) {
    console.error('Error: ALCHEMYST_AI_API_KEY environment variable is not set.');
    process.exit(1);
  }

  // 2. Parse CLI Arguments
  const args = process.argv.slice(2);
  let thresholdsCsv = '';
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--thresholds' && i + 1 < args.length) {
      thresholdsCsv = args[i + 1];
    } else if (args[i].startsWith('--thresholds=')) {
      thresholdsCsv = args[i].split('=')[1];
    }
  }

  if (!thresholdsCsv) {
    console.error('Error: --thresholds <csv> argument is required.');
    process.exit(1);
  }

  const thresholds = thresholdsCsv.split(',').map(val => {
    const num = parseFloat(val.trim());
    if (isNaN(num) || num < 0 || num > 1) {
      console.error(`Error: Invalid threshold value "${val}". Must be a number between 0 and 1.`);
      process.exit(1);
    }
    return num;
  });

  // 3. Read run-id
  const runIdPath = '/logs/artifacts/run-id';
  let runId = '';
  try {
    runId = fs.readFileSync(runIdPath, 'utf8').trim();
  } catch (err) {
    console.error(`Error reading run-id from ${runIdPath}:`, err);
    process.exit(1);
  }

  if (!runId) {
    console.error('Error: run-id is empty.');
    process.exit(1);
  }

  console.error(`Using run-id: ${runId}`);

  // 4. Initialize Alchemyst client
  const client = new AlchemystAI({ apiKey });

  // 5. Define Query and Corpus
  const query = 'What is quantum supremacy and how do quantum computers achieve it?';

  const documents = [
    {
      content: 'What is quantum supremacy and how do quantum computers achieve it? Quantum supremacy is achieved when a quantum computer performs a calculation that is impossible for classical computers. Quantum computers achieve this by leveraging qubits, superposition, and entanglement.',
      metadata: {
        file_name: `quantum_supremacy_core_${runId}.md`
      }
    },
    {
      content: 'Achieving quantum supremacy is a major milestone. A quantum computer uses quantum mechanics to process information, allowing it to solve specific complex problems exponentially faster than any classical supercomputer.',
      metadata: {
        file_name: `quantum_computing_milestone_${runId}.md`
      }
    },
    {
      content: 'Quantum computing is an emerging technology. Researchers are building quantum processors using superconducting qubits to explore quantum algorithms, though practical quantum computers are still in development.',
      metadata: {
        file_name: `quantum_computing_research_${runId}.md`
      }
    },
    {
      content: 'Supercomputers are high-performance classical computers. They perform massive parallel computations for scientific research, but they are limited by classical physics and do not use quantum principles.',
      metadata: {
        file_name: `classical_supercomputing_${runId}.md`
      }
    },
    {
      content: 'Baking a cake requires mixing flour, sugar, butter, and baking powder, then baking it in an oven.',
      metadata: {
        file_name: `cake_recipe_${runId}.md`
      }
    },
    {
      content: 'Photosynthesis is the process used by plants to convert light energy into chemical energy.',
      metadata: {
        file_name: `photosynthesis_process_${runId}.md`
      }
    }
  ];

  // 6. Ingest Corpus Idempotently
  console.error('Ingesting corpus...');
  try {
    await client.v1.context.add({
      documents: documents,
      context_type: 'resource',
      source: 'documentation',
      scope: 'internal'
    });
    console.error('✅ Corpus ingestion successful.');
  } catch (error: any) {
    const isConflict = 
      error.status === 409 || 
      error.statusCode === 409 || 
      (error.message && error.message.includes('409')) ||
      (error.message && error.message.toLowerCase().includes('conflict')) ||
      error.code === 'CONFLICT';

    if (isConflict) {
      console.error('⚠️ Ingestion conflict (409), documents already exist. Proceeding to search phase.');
    } else {
      console.error('Error during ingestion:', error);
      process.exit(1);
    }
  }

  // 7. Search for each threshold
  const results: { threshold: number; count: number }[] = [];

  for (const threshold of thresholds) {
    console.error(`Searching at threshold ${threshold}...`);
    try {
      const response = await client.v1.context.search({
        query: query,
        similarity_threshold: threshold,
        scope: 'internal'
      });
      const count = response.contexts?.length || 0;
