import AlchemystAI from '@alchemystai/sdk';

async function main() {
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!apiKey) {
    console.error('ALCHEMYST_AI_API_KEY is not set');
    process.exit(1);
  }
  const client = new AlchemystAI({ apiKey });
  const query = 'What is quantum supremacy and how do quantum computers achieve it?';

  console.log('--- Search with minimum_similarity_threshold: 0.5, similarity_threshold: 1.0 ---');
  let response = await client.v1.context.search({
    query: query,
    minimum_similarity_threshold: 0.5,
    similarity_threshold: 1.0,
    scope: 'internal',
    metadata: 'true'
  });
  console.log(JSON.stringify(response, null, 2));

  console.log('--- Search with minimum_similarity_threshold: 0.9, similarity_threshold: 1.0 ---');
  response = await client.v1.context.search({
    query: query,
    minimum_similarity_threshold: 0.9,
    similarity_threshold: 1.0,
    scope: 'internal',
    metadata: 'true'
  });
  console.log(JSON.stringify(response, null, 2));
}

main().catch(console.error);

